import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validatorsBySchema: WeakMap<object, ValidateFunction>;
}

interface ValidationErrorDetails {
  keyword?: string;
  instancePath?: string;
  params?: {missingProperty?: string; type?: string};
}

function describeValidationError(error: ValidationErrorDetails | undefined): {property: string; reason: string} {
  if (error?.keyword === 'required') {
    return {property: error.params?.missingProperty ?? 'input', reason: 'is required'};
  }
  if (error?.keyword === 'type') {
    return {
      property: error.instancePath?.replace(/^\//, '') || 'input',
      reason: `must be of type ${error.params?.type ?? 'the declared schema type'}`,
    };
  }
  return {
    property: error?.instancePath?.replace(/^\//, '') || 'input',
    reason: `failed ${error?.keyword ?? 'schema validation'}`,
  };
}

function schemaCompilationError(toolName: string, error: unknown): Error {
  const message = error instanceof Error ? error.message : String(error);
  return new Error(`Failed to compile inputSchema for tool '${toolName}': ${message}`);
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw schemaCompilationError(resolved.name, error);
      }
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validatorsBySchema: new WeakMap(),
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input and returns schema rejections; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator =
      tool.validator ?? tool.validatorsBySchema.get(definition.inputSchema) ?? this.ajv.compile(definition.inputSchema);
    if (!tool.validator) {
      tool.validatorsBySchema.set(definition.inputSchema, validator);
    }
    if (!validator(input)) {
      const error = validator.errors?.[0] as ValidationErrorDetails | undefined;
      const {property, reason} = describeValidationError(error);
      log.warn('tool', 'input rejected', {name, property, keyword: error?.keyword});
      return {result: `Input validation failed: property '${property}' ${reason}.`};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

function registerWeatherTool(registry: ToolRegistry, executorCalls: {value: number}): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls.value += 1;
      return 'sunny';
    }
  );
}

describe('ToolRegistry input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a rejection for missing required input without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executorCalls = {value: 0};
    registerWeatherTool(registry, executorCalls);

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required/i.test(response.result),
      executorCalls: executorCalls.value,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports the expected type for a rejected property without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      resultNamesFieldAndType: response.result.includes('identifier') && response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
      executorCalls,
    }).toEqual({resultNamesFieldAndType: true, leaksValue: false, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('names the tool when a static schema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_static_schema',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_static_schema/);
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('caches a function-valued schema validator by object reference', async () => {
    const registry = new ToolRegistry();
    const ajv = Reflect.get(registry, 'ajv') as {
      compile: (schema: object) => unknown;
    };
    const originalCompile = ajv.compile.bind(ajv);
    let compileCalls = 0;
    ajv.compile = schema => {
      compileCalls += 1;
      return originalCompile(schema);
    };
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'cached_weather',
        description: 'Get weather for a location',
        inputSchema: schema,
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    await registry.execute('cached_weather', {location: 'Paris'});
    schema.required = ['city'];
    const response = await registry.execute('cached_weather', {location: 'Paris'});

    expect({compileCalls, result: response.result, executorCalls}).toEqual({
      compileCalls: 1,
      result: 'sunny',
      executorCalls: 2,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: returns a rejection for missing required input without invoking the executor](../../src/orchestration/tools/registry.test.ts#L19), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: reports the expected type for a rejected property without exposing its value](../../src/orchestration/tools/registry.test.ts#L48)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: names the tool when a static schema cannot be compiled](../../src/orchestration/tools/registry.test.ts#L77), [validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules. ([validated by caches a function-valued schema validator by object reference](../../src/orchestration/tools/registry.test.ts#L85))

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

